'use strict';
const DBNAME='fitlocal-v1', STORE='records';let db, page='programs', programId=null, dayId=null, session=null, timerEnd=0,timerInterval=null, chartMetric='load';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], uid=()=>crypto.randomUUID(), clone=x=>structuredClone(x), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data={programs:[],library:[],history:[],oneRM:{}};let activeRestIndex=-1,editingHistoryId=null;
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open(DBNAME,1);r.onupgradeneeded=()=>r.result.createObjectStore(STORE);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function getRecord(k){return new Promise((resolve,reject)=>{const r=db.transaction(STORE).objectStore(STORE).get(k);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function putRecord(k,v){return new Promise((resolve,reject)=>{const t=db.transaction(STORE,'readwrite');t.objectStore(STORE).put(v,k);t.oncomplete=resolve;t.onerror=()=>reject(t.error)})}
let writeQueue=Promise.resolve();function save(){const snapshot=clone(data);writeQueue=writeQueue.then(()=>putRecord('data',snapshot)).catch(e=>{alert('Errore nel salvataggio locale: '+e.message)});return writeQueue}
function toast(t){const e=$('#toast');e.textContent=t;e.style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>e.style.display='none',2400)}
function btn(t,action,cls='secondary'){return `<button class="btn ${cls}" data-action="${action}">${t}</button>`}
function trash(action,attrs='',label='Elimina'){return `<button type="button" class="trash-btn" data-action="${action}" ${attrs} title="${esc(label)}" aria-label="${esc(label)}"><svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 7h16M9 7V4h6v3M6 7l1 13h10l1-13M10 11v6M14 11v6"/></svg></button>`}
function sessionTime(date){const d=new Date(date);return Number.isNaN(d.getTime())?'—':d.toLocaleString('it-IT',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false})}
function linkedRoot(items,item){let current=item,seen=new Set();while(current?.relation?.parentId&&!seen.has(current.id)){seen.add(current.id);const parent=items.find(x=>x.id===current.relation.parentId);if(!parent)break;current=parent}return current?.id||item.id}
function moveLinkedGroup(items,id,dir){const target=items.find(x=>x.id===id);if(!target)return false;const groups=[];for(const item of items){const root=linkedRoot(items,item);let g=groups.find(x=>x.root===root);if(!g){g={root,items:[]};groups.push(g)}g.items.push(item)}const index=groups.findIndex(g=>g.root===linkedRoot(items,target));const next=index+dir;if(next<0||next>=groups.length)return false;[groups[index],groups[next]]=[groups[next],groups[index]];items.splice(0,items.length,...groups.flatMap(g=>g.items));return true}
function nextRelationNotice(items,i){const following=items.filter(x=>x.relation?.parentId===items[i].id);return following.map(next=>`<div class="relation-next">↓ A seguire · ${esc(RELATIONS[next.relation.type]||'Esercizio collegato')}${next.relation.type==='jump'?' · '+Number(next.relation.betweenRest||0)+' s':''}</div>`).join('')}
function canonicalUnit(t){return ['rm','percent'].includes(t)?null:(t||'kg')}
function historicalUnits(k){const found=new Set();for(const h of data.history||[])for(const e of h.exercises||[])if(keyEx(e)===k)for(const set of e.setsDone||[])if(set.done){const u=canonicalUnit(set.loadType||e.loadType);if(u)found.add(u)}return found}
function unitForExercise(ex){const units=historicalUnits(keyEx(ex));return units.size===1?[...units][0]:null}
function ensureUnit(ex,t){const unit=canonicalUnit(t);if(!unit)return;const existing=historicalUnits(keyEx(ex));if(existing.size>1)throw Error('Questo esercizio ha unità storiche incompatibili ('+[...existing].join(', ')+'). Correggile nello storico prima di registrare nuovi set.');if(existing.size&& !existing.has(unit))throw Error('Per questo esercizio lo storico utilizza '+[...existing][0]+'. Modifica prima i set nello storico per cambiare unità.');}
function displayLoadUnit(t){return t==='bwplus'?'kg + BW':t==='bw'?'BW (peso corporeo)':t==='kg'?'kg':t==='percent'?'%':t==='rm'?'RM':t==='duration'?'durata':t==='distance'?'distanza':t==='pace'?'passo':t||'kg'}
function unitForKey(k){const u=historicalUnits(k);return u.size===1?[...u][0]:null}
function bestPRSet(k){
  // Identical source and ordering to the weighted PR displayed in Statistics.
  const expected=unitForKey(k);if(!expected||!['kg','bwplus'].includes(expected))return null;const candidates=filteredStatHistory().flatMap(h=>h.exercises.filter(e=>eligibleStats(e)&&keyEx(e)===k).flatMap(e=>(e.setsDone||[]).filter(x=>x.done).map(x=>{
    const t=x.loadType||e.loadType;
    const kg=['kg','bwplus'].includes(t)?Number(x.loadValue):(['rm','percent'].includes(t)&&Number(x.effectiveKg)>0?Number(x.effectiveKg):null);
    return {kg:t===expected?kg:null,reps:clusterStatsReps(e,x),date:h.date,unit:expected};
  }).filter(x=>x.kg>0&&Number.isFinite(x.reps)&&x.reps>0)));
  candidates.sort((a,b)=>b.kg-a.kg||b.reps-a.reps);
  return candidates[0]||null;
}
function estimatePR(k){const best=bestPRSet(k);return best?{...best,estimated:best.reps===1?best.kg:best.kg*(1+best.reps/30)}:null}

function field(label,key,value='',type='text',extra=''){const suggestible=type==='text'&&['name','variant','equipment','brand','muscles'].includes(key);const opts=suggestible?[...new Set([...data.library,...data.programs.flatMap(p=>p.days.flatMap(d=>d.exercises)),...(session?.exercises||[])].flatMap(e=>key==='muscles'?String(e.muscles||'').split(',').map(m=>m.trim()):[e[key]]).filter(v=>typeof v==='string'&&v.trim()))].sort((a,b)=>a.localeCompare(b,'it')):[];return `<label class="field"><span>${label}</span><div class="field-input-row"><input data-field="${key}" type="${type}" value="${esc(value)}" ${extra}>${opts.length?`<button type="button" class="suggest-toggle" data-action="showSuggestions" data-key="${key}" aria-label="Mostra suggerimenti per ${esc(label)}" title="Scorri i valori già utilizzati">⌄</button>`:''}</div></label>`}
function showSuggestions(key){const values=[...new Set([...data.library,...data.programs.flatMap(p=>p.days.flatMap(d=>d.exercises)),...(session?.exercises||[])].flatMap(e=>key==='muscles'?String(e.muscles||'').split(',').map(m=>m.trim()):[e[key]]).filter(v=>typeof v==='string'&&v.trim()))].sort((a,b)=>a.localeCompare(b,'it'));const form=$('#exerciseForm');if(!form)return;const input=form.querySelector(`[data-field="${key}"]`);if(!input)return;const current=input.value;const panel=document.createElement('div');panel.className='suggest-panel';panel.innerHTML=`<div class="row"><strong>Valori già usati</strong><button type="button" class="btn secondary small" data-action="closeSuggestions">Chiudi</button></div><div class="suggest-list">${values.map((v,i)=>`<button type="button" class="suggest-option" data-action="chooseSuggestion" data-key="${key}" data-option="${i}">${esc(v)}</button>`).join('')}</div>`;document.querySelectorAll('.suggest-panel').forEach(x=>x.remove());if(key==='muscles')panel.insertAdjacentHTML('beforeend','<p class="hint">Il primo muscolo della lista è Prime Mover; i successivi sono Second Movers.</p>');input.closest('.field').append(panel);panel.dataset.values=JSON.stringify(values);input.value=current}

function area(label,key,value=''){return `<label class="field"><span>${label}</span><textarea data-field="${key}">${esc(value)}</textarea></label>`}
function select(label,key,choices,value){return `<label class="field"><span>${label}</span><select data-field="${key}">${choices.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`}
const types=[['kg','Kg'],['bw','BW (corpo libero)'],['bwplus','BW + kg'],['rm','RM'],['percent','Percentuale (%)'],['duration','Durata'],['distance','Distanza'],['pace','Passo']];
const intensities=[['','Nessuna'],['RPE','RPE'],['RIR','RIR'],['Zona','Zona corsa']];
function intensityValues(t){return t==='RPE'?[5,5.5,6,6.5,7,7.5,8,8.5,9,9.5,10]:t==='RIR'?[5,4,3,2,1,0]:t==='Zona'?[1,2,3,4,5]:[]}
function loadUnit(t){return t==='duration'?[['sec','Secondi'],['min','Minuti']]:t==='distance'?[['m','Metri'],['km','Chilometri']]:[['kg','kg']]}
function blankEx(){return {category:'normal',clusterCount:2,id:uid(),name:'',variant:'',equipment:'',brand:'',muscles:'',settings:[],pace:'',sets:3,reps:'10',loadType:'kg',loadValue:'',loadUnit:'kg',intensityType:'',intensityValue:'',notes:'',restSeconds:90}}
function program(){return data.programs.find(x=>x.id===programId)}function day(){return program()?.days.find(x=>x.id===dayId)}
function header(title,back){return `<button class="back" data-action="${back}">‹ Indietro</button><h2>${esc(title)}</h2>`}
function render(){const root=$('#app');if(page==='programs')root.innerHTML=renderPrograms();if(page==='days')root.innerHTML=renderDays();if(page==='editor')root.innerHTML=renderEditor();if(page==='session')root.innerHTML=renderSession();if(page==='history')root.innerHTML=renderHistory();if(page==='stats')root.innerHTML=renderStats();if(page==='library')root.innerHTML=renderLibrary();if(page==='settings')root.innerHTML=renderSettings();if(page==='profile')root.innerHTML=renderProfile();$$('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));bindDynamic();}
function renderPrograms(){return `${session?`<div class="notice">Allenamento in corso <button class="btn small" data-action="resumeSession">Riprendi</button></div>`:''}<div class="row"><h2>Programmi</h2>${btn('+ Nuovo','newProgram','')}</div>${data.programs.length?data.programs.map((p,i)=>`<article class="card"><div class="row"><div><div class="title">${esc(p.name)}</div><div class="sub">${p.days.length} giornate</div></div><button class="iconbtn" data-action="openProgram" data-id="${p.id}">Apri ›</button></div><div class="toolbar"><button class="btn secondary small" data-action="moveProgram" data-id="${p.id}" data-dir="-1" ${i===0?'disabled':''}>↑</button><button class="btn secondary small" data-action="moveProgram" data-id="${p.id}" data-dir="1" ${i===data.programs.length-1?'disabled':''}>↓</button><button class="btn secondary small" data-action="renameProgram" data-id="${p.id}">Rinomina</button><button class="btn secondary small" data-action="copyProgram" data-id="${p.id}" aria-label="Duplica" title="Duplica">⧉</button>${trash('deleteProgram',`data-id="${p.id}"`)}</div></article>`).join(''):'<div class="empty">Crea il tuo primo programma.</div>'}`}
function renderDays(){const p=program();if(!p)return '';return `${session?`<div class="notice">Sessione in corso <button class="btn small" data-action="resumeSession">Riprendi</button></div>`:''}${header(p.name,'goPrograms')}<div class="toolbar">${btn('+ Nuova giornata','newDay','')}</div>${p.days.map((d,i)=>`<article class="card"><div class="row"><div><div class="title">${esc(d.name)}</div><div class="sub">${d.exercises.length} esercizi</div></div></div><div class="toolbar"><button class="btn secondary small" data-action="moveDay" data-id="${d.id}" data-dir="-1" ${i===0?'disabled':''}>↑</button><button class="btn secondary small" data-action="moveDay" data-id="${d.id}" data-dir="1" ${i===p.days.length-1?'disabled':''}>↓</button><button class="btn secondary small" data-action="editDay" data-id="${d.id}">Modifica</button><button class="btn secondary small" data-action="copyDay" data-id="${d.id}" aria-label="Duplica" title="Duplica">⧉</button><button class="btn secondary small" data-action="renameDay" data-id="${d.id}">Rinomina</button><button class="btn small" data-action="startDay" data-id="${d.id}">▶ Avvia</button>${trash('deleteDay',`data-id="${d.id}"`)}</div></article>`).join('')||'<div class="empty">Aggiungi una giornata per iniziare.</div>'}`}
function compact(ex){return `<div class="compact"><div><small>Sets</small>${esc(ex.sets)}</div><div><small>${['distance','pace'].includes(ex.loadType)?(ex.loadType==='pace'?'Passo':'Distanza'):ex.loadType==='duration'?'Durata':'Reps'}</small>${esc(ex.loadType==='pace'?ex.pace||'—':ex.loadType==='distance'?ex.loadValue||'—':ex.loadType==='duration'?loadLabel(ex):ex.reps)}</div><div><small>Carico</small>${esc(loadLabel(ex))}</div><div><small>Recupero</small>${fmtTime(ex.restSeconds)}</div></div>`}
function exerciseTitle(ex){return `<h3>${esc(ex.name||'Esercizio senza nome')} <span class="ex-variant">${esc(ex.variant||'')}</span></h3><div class="sub">${esc(ex.equipment||'Attrezzo non indicato')} · ${esc(ex.brand||'Linea non indicata')}</div>`}
function sortedArchive(items){return [...items].sort((a,b)=>Number(!!b.favorite)-Number(!!a.favorite)||String(a.name||'').localeCompare(String(b.name||''),'it')||String(a.variant||'').localeCompare(String(b.variant||''),'it'))}
function defaultFixed(){return Array.from({length:5},()=>({sets:'',loadType:'kg',loadValue:'',reps:'',intensityValue:''}))}
function validFixedOption(o){return !!(o&&Number(o.sets)>0&&String(o.reps??'').trim()&&((o.loadType==='RPE'&&intensityValues('RPE').includes(Number(o.intensityValue)))||(o.loadType!=='RPE'&&String(o.loadValue??'').trim()!==''&&Number.isFinite(Number(o.loadValue)))))}
function fixedTables(items,ex,mode){const tables=ex.fixedTables||[];return tables.map((t,ti)=>`<div class="fixed-table"><div class="row"><div class="toolbar"><button class="btn secondary small" data-action="editFixed" data-id="${ex.id}" data-table="${ti}" data-context="${mode}">Modifica</button>${trash('deleteFixed',`data-id="${ex.id}" data-table="${ti}" data-context="${mode}"`,'Elimina tabella')}</div></div><div class="fixed-grid">${(t.options||[]).map((o,oi)=>`<button class="fixed-option ${t.selected===oi?'selected':''}" ${validFixedOption(o)?'':'disabled'} data-action="applyFixed" data-id="${ex.id}" data-table="${ti}" data-option="${oi}" data-context="${mode}"><b>${oi+1}</b>${validFixedOption(o)?`<span>${esc(o.sets)} sets</span><span>${o.loadType==='RPE'?'RPE '+esc(o.intensityValue):esc(o.loadValue)+' '+(o.loadType==='percent'?'%':o.loadType==='bwplus'?'kg + BW':'kg')}</span><span>${esc(o.reps)} reps</span>`:'<span>—</span>'}</button>`).join('')}</div></div>`).join('')}
function fixedTop(context){return `<div class="toolbar"><button class="btn secondary small" data-action="newFixed" data-context="${context}">+ Carichi fissi</button></div>`}
function fixedEditor(ex,tableIndex,context){const t=ex.fixedTables?.[tableIndex]||{options:defaultFixed()};modal({title:'Carichi fissi · '+esc(ex.name),body:`<p class="hint">Compila solo le colonne desiderate: Sets, Reps e Carico oppure RPE.</p><div class="fixed-edit-grid">${Array.from({length:5},(_,i)=>{const o=t.options?.[i]||defaultFixed()[i];return `<div class="fixed-edit-col"><b>${i+1}</b><label>Sets<input type="number" min="1" max="99" data-fix="sets" data-col="${i}" value="${esc(o.sets??'')}"></label><label>Tipo<select data-fix="loadType" data-col="${i}">${[['kg','kg'],['bwplus','BW + kg'],['percent','%'],['RPE','RPE']].map(([v,l])=>`<option value="${v}" ${o.loadType===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Carico<input type="number" step="any" data-fix="loadValue" data-col="${i}" value="${esc(o.loadValue||'')}"></label><label>RPE<input type="number" step="0.5" min="5" max="10" data-fix="intensityValue" data-col="${i}" value="${esc(o.intensityValue||'')}"></label><label>Reps<input data-fix="reps" data-col="${i}" value="${esc(o.reps??'')}"></label></div>`}).join('')}</div><div class="toolbar"><button class="btn" data-action="saveFixed" data-id="${ex.id}" data-table="${tableIndex}" data-context="${context}">Salva tabella</button></div>`})}
function updateActuals(ex){const n=Math.max(1,Math.min(99,Number(ex.sets)||1));ex.setsDone??=[];while(ex.setsDone.length<n)ex.setsDone.push({done:false});if(ex.setsDone.length>n&&!ex.setsDone.slice(n).some(x=>x.done))ex.setsDone.length=n;for(const x of ex.setsDone){if(x.done)continue;x.reps=String(ex.reps||'').split(/[-–]/).at(-1).trim();x.loadType=['rm','percent'].includes(ex.loadType)?(unitForExercise(ex)||'kg'):ex.loadType;x.loadUnit=['rm','percent'].includes(ex.loadType)?'kg':(ex.loadUnit||'kg');x.loadValue=['rm','percent'].includes(ex.loadType)?'':(ex.loadValue||'');x.pace=ex.pace||'';delete x.effectiveKg}}
function applyFixed(ex,ti,oi,isSession){const t=ex.fixedTables?.[ti],o=t?.options?.[oi];if(!validFixedOption(o))return;t.selected=oi;ex.sets=Number(o.sets)||1;ex.reps=String(o.reps||'');if(o.loadType==='RPE'){ex.intensityType='RPE';ex.intensityValue=String(o.intensityValue||'');ex.loadType=unitForExercise(ex)||ex.loadType||'kg';ex.loadUnit='kg';ex.loadValue='';}else{ex.intensityType='';ex.intensityValue='';ex.loadType=o.loadType;ex.loadUnit='kg';ex.loadValue=String(o.loadValue??'');}if(isSession)updateActuals(ex)}
function plannedReps(ex){const parts=String(ex.reps||'').split(/[-–]/);return Number(parts.at(-1)?.trim())||0}
function setRPE(ex,set){if(set.rpe!==undefined&&set.rpe!==null&&String(set.rpe).trim()!=='')return Number(set.rpe);return ex.intensityType==='RPE'&&String(ex.intensityValue||'').trim()!==''?Number(ex.intensityValue):null}
function rpeBest(ex,rpe){const wanted=plannedReps(ex);const target=Number(rpe);if(!wanted||!Number.isFinite(target))return null;const values=historyMatching(ex).filter(eligibleStats).flatMap(h=>{const date=h.date||'';return (h.setsDone||[]).filter(x=>x.done&&Number(x.reps)===wanted&&setRPE(h,x)===target).map(x=>({kg:effectiveKg(h,x),reps:Number(x.reps),type:x.loadType||h.loadType,value:x.loadValue,unit:x.loadUnit||h.loadUnit,date}))}).filter(x=>Number.isFinite(x.kg)&&x.kg>0);values.sort((a,b)=>b.kg-a.kg||b.date.localeCompare(a.date));return values[0]||null}
function rpeBestLegacy(ex,rpe){const values=historyMatching(ex).filter(eligibleStats).flatMap(h=>h.intensityType==='RPE'&&String(h.intensityValue)===String(rpe)?(h.setsDone||[]).filter(x=>x.done).map(x=>({kg:effectiveKg(h,x),reps:Number(x.reps),type:x.loadType||h.loadType,value:x.loadValue,unit:x.loadUnit||h.loadUnit})):[]).filter(x=>x.kg!==null&&x.kg>0&&x.reps>0);values.sort((a,b)=>b.kg-a.kg||b.reps-a.reps);return values[0]||null}
function rpeHistoryBest(ex,rpe){const values=historyMatching(ex).filter(eligibleStats).flatMap(h=>(h.setsDone||[]).filter(x=>x.done&&setRPE(h,x)===Number(rpe)).map(x=>({kg:effectiveKg(h,x),reps:Number(x.reps),date:h.date}))).filter(x=>Number.isFinite(x.kg)&&x.kg>0);values.sort((a,b)=>b.kg-a.kg||b.date.localeCompare(a.date));return values[0]||null}
function rpeKeys(){return sortedArchive([...new Map([...data.library,...data.history.flatMap(h=>h.exercises||[])].map(e=>[keyEx(e),e])).values()])}
function showRPEHistory(key){if(!key){modal({title:'Storico RPE · Esercizi',body:rpeKeys().map(e=>`<button class="btn secondary" style="display:block;width:100%;margin:6px 0;text-align:left" data-action="rpeExercise" data-key="${esc(keyEx(e))}">${esc(e.name)} · ${esc(e.variant)} · ${esc(e.equipment)} · ${esc(e.brand)}</button>`).join('')||'<p>Nessun esercizio.</p>'});return}const ex=rpeKeys().find(e=>keyEx(e)===key);if(!ex)return;const rows=intensityValues('RPE').map(r=>({r,v:rpeHistoryBest(ex,r)})).filter(x=>x.v);modal({title:'Storico RPE · '+esc(ex.name),body:rows.map(x=>`<div class="card"><strong>RPE ${x.r}</strong><div>${x.v.kg.toFixed(2)} kg × ${x.v.reps} reps</div></div>`).join('')||'<p>Nessuna prestazione RPE registrata.</p>'})}
function applySuggestionSets(e,s){if(!s)return;try{ensureUnit(e,s.loadType||e.loadType)}catch(err){toast(err.message);return}if(e.category==='cluster'&&s.clusterCount){e.clusterCount=s.clusterCount;for(const v of e.setsDone)if(!v.done)v.clusterCount=s.clusterCount;}const oldType=s.loadType||'kg',convert=['rm','percent'].includes(oldType),kg=convert?(Number(s.effectiveKg)||effectiveKg(e,s)):null;if(convert&&!(kg>0)){toast('Carico storico non convertibile in kg');return}for(const x of e.setsDone){if(x.done)continue;x.reps=String(s.reps);x.loadType=convert?(unitForExercise(e)||'kg'):oldType;x.loadUnit=convert?'kg':(s.loadUnit||'kg');x.loadValue=String(convert?kg:(s.loadValue??s.kg??''));delete x.effectiveKg}}
function renderEditor(){const d=day();if(!d)return '';const controls=`<div class="toolbar">${btn('+ Nuovo esercizio','addExercise','')}${btn('Archivio','pickLibrary')}</div>`;return `${header(d.name,'goDays')}${fixedTop('day')}${controls}${d.exercises.map((ex,i)=>`<article class="card exercise ${ex.category==='top'?'top-sets':''} ${ex.relation?.parentId?'linked-exercise linked-arrow':''}">${relationBadge(ex)}${fixedTables(d.exercises,ex,'day')}<div class="row"><div>${exerciseTitle(ex)}</div><div class="row"><button class="iconbtn" data-action="editExercise" data-id="${ex.id}">Modifica</button>${trash('deleteExercise',`data-id="${ex.id}"`)}</div></div><div class="info-intensity-row"><details><summary>Altre informazioni</summary>${info(ex)}</details><span class="intensity-summary">Intensità: ${esc(ex.intensityType?ex.intensityType+' '+(ex.intensityValue||''):'—')}</span></div>${compact(ex)}${ex.category==='cluster'?`<p class="hint">Cluster sets · 2 cluster iniziali per set, modificabili durante l’allenamento.</p>`:''}${nextRelationNotice(d.exercises,i)}<div class="exercise-move"><button class="btn secondary small" data-action="moveExercise" data-id="${ex.id}" data-dir="-1" ${i===0?'disabled':''}>↑</button><button class="btn secondary small" data-action="moveExercise" data-id="${ex.id}" data-dir="1" ${i===d.exercises.length-1?'disabled':''}>↓</button></div></article>`).join('')||'<div class="empty">Nessun esercizio in questa giornata.</div>'}${controls}<div class="toolbar">${btn('‹ Indietro','goDays','secondary')}</div>`}
function fmtTime(s){s=Number(s)||0;return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`}
function loadLabel(ex){if(ex.loadType==='bw')return 'BW';if(ex.loadType==='bwplus')return `${ex.loadValue||'—'} kg + BW`;if(ex.loadType==='rm')return `${ex.loadValue||'—'} RM`;if(ex.loadType==='percent')return `${ex.loadValue||'—'}%`;return `${ex.loadValue||'—'} ${ex.loadUnit||'kg'}`}
function info(ex){return `<div class="sub">Muscoli: ${esc(ex.muscles||'—')}</div><div class="sub">Indicazioni: ${esc(ex.notes||'—')}</div>`}
function modal(content){$('#modal').className='modaloverlay';$('#modal').innerHTML=`<div class="sheet"><div class="sheethead row"><h2>${content.title||'Modifica'}</h2><button class="iconbtn" data-action="closeModal">✕</button></div>${content.body}</div>`}
function closeModal(){$('#modal').className='hidden';$('#modal').innerHTML=''}
let pendingRelation=null;function exerciseForm(ex,context){const e=clone(ex);pendingRelation=e.relation?{id:e.id,relation:clone(e.relation)}:null;modal({title:context==='library'?'Scheda archivio':'Modifica esercizio',body:`<form id="exerciseForm">${field('Nome esercizio *','name',e.name,'text','required')}${field('Variante','variant',e.variant)}<div class="cols">${field('Attrezzo / macchinario','equipment',e.equipment)}${field('Linea','brand',e.brand)}</div>${field('Muscoli coinvolti (separati da virgola)','muscles',e.muscles)}<div class="card"><div class="row"><h3>Setting macchinario</h3><button type="button" class="btn secondary small" data-action="addSetting">+ Dettaglio</button></div><div id="settingsList">${(e.settings||[]).map(settingRow).join('')}</div></div>${context==='library'?'':`<div class="cols3">${field('Sets','sets',e.sets,'number','min="1" step="1" required')}<div id="repsField">${field('Reps (es. 8 o 8-12)','reps',e.reps)}</div>${field('Recupero (sec)','restSeconds',e.restSeconds,'number','min="0" step="1"')}</div><div class="cols">${select('Tipo carico / prestazione','loadType',types,e.loadType)}<div id="loadFields"></div></div><div class="cols">${select('Tipo intensità','intensityType',intensities,e.intensityType)}<div id="intensityFields"></div></div>`}${area('Indicazioni sull’esecuzione','notes',e.notes)}<div class="toolbar"><button class="btn" type="submit">Salva esercizio</button></div></form>`});$('#exerciseForm').dataset.id=e.id;$('#exerciseForm').dataset.category=e.category||e.relation?.type||'normal';$('#exerciseForm').dataset.relation=e.relation?JSON.stringify(e.relation):'';$('#exerciseForm').dataset.context=context;$('#exerciseForm').dataset.loadValue=e.loadValue??'';$('#exerciseForm').dataset.loadUnit=e.loadUnit||'kg';$('#exerciseForm').dataset.pace=e.pace||'';$('#exerciseForm').dataset.intensityValue=e.intensityValue??'';if(context!=='library'){drawLoadFields();drawIntensityFields();}}
const CATEGORIES=[['normal','Normal sets'],['top','Top sets'],['backoff','Back off sets'],['drop','Drop sets'],['jump','Jump sets'],['super','Super sets'],['giant','Giant sets'],['cluster','Cluster sets']];
function categoryPicker(context,method,sourceId=''){const items=context==='session'?session.exercises:day().exercises;modal({title:'Categoria dei set',body:`<p class="hint">Scegli la categoria prima di ${method==='archive'?'selezionare dall’archivio':'creare l’esercizio'}.</p><div class="category-options">${CATEGORIES.map(([k,v])=>`<button class="btn secondary" data-action="chooseCategory" data-category="${k}" data-context="${context}" data-method="${method}" data-source="${sourceId}">${v}</button>`).join('')}</div>`})}
function categoryRelationPicker(category,context,method){const items=context==='session'?session.exercises:day().exercises;const linked=['backoff','drop','jump','super','giant'].includes(category);if(!linked)return continueCategory({category},context,method);if(!items.length){alert('Per collegare questa categoria devi prima aggiungere un esercizio alla giornata.');return}modal({title:'Collega '+(RELATIONS[category]||category),body:`<label class="field"><span>Esercizio di riferimento</span><select id="categoryParent">${items.map(e=>`<option value="${esc(e.id)}">${esc(e.name||'Esercizio senza nome')}</option>`).join('')}</select></label>${category==='jump'?'<label class="field"><span>Recupero Jump sets (secondi)</span><input id="categoryRest" type="number" min="0" step="1" value="0"></label>':''}<button class="btn" data-action="confirmCategory" data-category="${category}" data-context="${context}" data-method="${method}">Continua</button>`})}
function continueCategory(chosen,context,method){const relation=chosen.relation;const ex=blankEx();ex.category=chosen.category;if(relation)ex.relation=relation;if(method==='archive'){modal({title:'Scegli dall’archivio',body:`<div class="cols">${field('Nome','pickName')}${field('Muscoli','pickMuscles')}${field('Attrezzo','pickEquipment')}${field('Linea','pickBrand')}</div><div id="pickResults"></div>`});$('#modal').dataset.pickContext=context;$('#modal').dataset.category=chosen.category;$('#modal').dataset.relation=relation?JSON.stringify(relation):'';drawPick()}else exerciseForm(ex,context==='session'?'session-new':'day')}
function distributeClusters(reps,count){const n=Math.max(0,Number.parseInt(reps)||0),c=Math.max(2,Math.min(50,Number(count)||2));return Array.from({length:c},(_,i)=>Math.floor(n/c)+(i<n%c?1:0))}
function clusterStatsReps(e,s){return (e.category==='cluster'||s.clusters?.length)?Number(s.clusters?.[0]?.reps??distributeClusters(s.reps,e.clusterCount)[0]):Number(s.reps)}
function clusterControls(e,i,s,j){if((e.category||'normal')!=='cluster')return '';const count=Math.max(2,Number(s.clusterCount||e.clusterCount)||2),reps=distributeClusters(s.reps,count);return `<div class="cluster-panel"><div class="row"><strong>Cluster (${count})</strong><div class="toolbar"><button class="btn secondary small" data-action="removeCluster" data-index="${i}" data-set="${j}" ${count<=2?'disabled':''}>−</button><button class="btn secondary small" data-action="addCluster" data-index="${i}" data-set="${j}">+</button></div></div><div class="cluster-chips">${reps.map((n,k)=>`<span>${k+1}: ${n} reps · ${esc(actualSetLabel(e,s))}</span>`).join('')}</div></div>`}
function settingRow(s={label:'',value:''}){return `<div class="cols settingRow"><label class="field"><span>Dettaglio</span><input class="settingLabel" value="${esc(s.label)}" placeholder="Sedile"></label><label class="field"><span>Valore</span><input class="settingValue" value="${esc(s.value)}" placeholder="4"></label>${trash('removeSetting','','Rimuovi dettaglio')}</div>`}
function drawLoadFields(){const f=$('#exerciseForm');if(!f)return;const t=f.querySelector('[data-field="loadType"]').value;const v=f.dataset.loadValue,u=f.dataset.loadUnit;const isDistance=t==='distance',isPace=t==='pace',isDuration=t==='duration';const reps=$('#repsField');if(reps)reps.style.display=isDistance||isDuration||isPace?'none':'';$('#loadFields').innerHTML=t==='bw'?'<p class="hint">Corpo libero, senza sovraccarico.</p>':`${field(isDuration?'Durata':isDistance?'Distanza':isPace?'Distanza (km)':t==='rm'?'Numero RM':t==='percent'?'Percentuale 1–100':'Valore','loadValue',v,'number',`step="any" min="0" ${t==='percent'?'max="100"':''}`)}${["duration","distance"].includes(t)?select('Unità','loadUnit',loadUnit(t),u):''}${isPace?field('Passo (mm:ss/km, es. 5:30)','pace',f.dataset.pace||''):''}${['rm','percent'].includes(t)?`<p class="hint" id="loadEstimate">${esc(estimateLabel(t,v,f))}</p>`:''}`;}
function estimateLabel(t,v,f){const ex={name:f.querySelector('[data-field="name"]')?.value,variant:f.querySelector('[data-field="variant"]')?.value,equipment:f.querySelector('[data-field="equipment"]')?.value,brand:f.querySelector('[data-field="brand"]')?.value};const rm=current1RM(keyEx(ex));if(!rm)return '1RM non disponibile: inseriscilo nelle statistiche o registra set in kg.';const kg=t==='percent'?rm*Number(v)/100:rm/(1+Math.max(0,Number(v)||1)/30);const unit=displayLoadUnit(unitForExercise(ex)||'kg');return v!==''?`≈ ${kg.toFixed(2)} ${unit} (1RM ${rm.toFixed(2)} ${unit})`:`1RM attuale: ${rm.toFixed(2)} kg`}
function parsePace(v){const x=String(v||'').trim().replace(',','.');if(!x)return null;if(/^\d+:([0-5]\d)$/.test(x)){const [m,sec]=x.split(':').map(Number);return m*60+sec}const n=Number(x);return Number.isFinite(n)&&n>0?n*60:null}
function migrateLegacyRMKeys(){
  // Retain legacy keys, and copy a manual 1RM only if its former three-field identity
  // corresponds to exactly one branded exercise in the existing data.
  const exercises=[...data.library,...data.programs.flatMap(p=>p.days.flatMap(d=>d.exercises)),...data.history.flatMap(h=>h.exercises||[])];
  let changed=false;
  for(const [oldKey,value] of Object.entries(data.oneRM||{})){
    if(oldKey.split('|').length!==3)continue;
    const matches=[...new Set(exercises.filter(e=>keyEx(e).split('|').slice(0,3).join('|')===oldKey).map(keyEx))];
    if(matches.length===1&&data.oneRM[matches[0]]===undefined){data.oneRM[matches[0]]=value;changed=true;}
  }
  return changed;
}
function current1RM(k){const manual=Number(data.oneRM?.[k]);if(manual>0)return manual;return estimatePR(k)?.estimated||null}
function effectiveKg(e,s){const t=s.loadType||e.loadType,v=Number(s.loadValue);if(t==='kg'||t==='bwplus')return s.loadValue!==''&&Number.isFinite(v)?v:null;if(t==='percent'||t==='rm'){if(s.effectiveKg!==undefined&&s.effectiveKg!==null&&s.effectiveKg!==''&&Number.isFinite(Number(s.effectiveKg))&&Number(s.effectiveKg)>0)return Number(s.effectiveKg);const rm=current1RM(keyEx(e));if(!rm||s.loadValue===''||!Number.isFinite(v)||v<=0)return null;return t==='percent'?rm*v/100:rm/(1+v/30)}return null}
function actualSetLabel(e,s){const t=s.loadType||e.loadType;if(t==='rm'||t==='percent'){const kg=effectiveKg(e,s);return kg===null?`${esc(s.loadValue)} ${t==='rm'?'RM':'%'} (1RM non disponibile)`:`${kg.toFixed(2)} kg (${esc(s.loadValue)}${t==='rm'?' RM':'%'})`}if(t==='bw')return 'BW';return `${esc(s.loadValue)} ${esc(s.loadUnit||e.loadUnit||'kg')}`}

function drawIntensityFields(){const f=$('#exerciseForm');if(!f)return;const t=f.querySelector('[data-field="intensityType"]').value;$('#intensityFields').innerHTML=t?select('Valore intensità','intensityValue',intensityValues(t).map(x=>[String(x),String(x)]),f.dataset.intensityValue):''}
function formEx(){const f=$('#exerciseForm');const x=blankEx();x.id=f.dataset.id;const original=[...data.library,...data.programs.flatMap(p=>p.days.flatMap(d=>d.exercises)),...(session?.exercises||[])].find(e=>e.id===x.id);if(f.dataset.context==='library'&&original)Object.assign(x,clone(original));if(original?.relation)x.relation=clone(original.relation);if(original?.category)x.category=original.category;if(original?.clusterCount)x.clusterCount=original.clusterCount;if(original?.fixedTables)x.fixedTables=clone(original.fixedTables);if(pendingRelation?.id===x.id)x.relation=clone(pendingRelation.relation);if(f.dataset.category)x.category=f.dataset.category;if(f.dataset.relation)x.relation=JSON.parse(f.dataset.relation);f.querySelectorAll('[data-field]').forEach(el=>x[el.dataset.field]=el.value);x.sets=Math.max(1,Math.floor(Number(x.sets)||1));x.restSeconds=Math.max(0,Math.floor(Number(x.restSeconds)||0));x.settings=[...f.querySelectorAll('.settingRow')].map(r=>({label:r.querySelector('.settingLabel').value.trim(),value:r.querySelector('.settingValue').value.trim()})).filter(s=>s.label||s.value);x.name=x.name.trim();x.reps=x.reps.trim();if(!['duration','distance','pace'].includes(x.loadType)&&!/^\d+(\s*[-–]\s*\d+)?$/.test(x.reps))throw Error('Le reps devono essere un numero o un intervallo (es. 8-12).');if(!x.name)throw Error('Inserisci il nome dell’esercizio.');if(x.loadType==='pace'&&x.pace&&parsePace(x.pace)===null)throw Error('Passo non valido. Usa 5:30 oppure 5,5 min/km.');if(x.loadType==='bw')x.loadValue='';if(!['duration','distance','pace'].includes(x.loadType))x.loadUnit='kg';if(x.loadType==='pace')x.loadUnit='km';if(x.loadType==='percent'&&x.loadValue!==''&&(Number(x.loadValue)<1||Number(x.loadValue)>100))throw Error('Percentuale da 1 a 100.');if(x.loadValue!==''&&Number(x.loadValue)<0)throw Error('Valore non negativo.');if(!x.intensityType)x.intensityValue='';return x}
function historyMatching(ex){return data.history.flatMap(h=>h.exercises.map(e=>({...e,date:h.date,sessionId:h.id,programName:h.programName,dayName:h.dayName}))).filter(e=>keyEx(e)===keyEx(ex)).sort((a,b)=>b.date.localeCompare(a.date))}
const RELATIONS={backoff:'Back off sets',drop:'Drop sets',super:'Super sets',giant:'Giant sets',jump:'Jump sets'};
function relationBadge(e){const c=e.category||e.relation?.type||'normal';if(c==='normal'||c==='top')return '';return `<span class="relation-badge">${c==='cluster'?'Cluster sets':esc(RELATIONS[c]||c)}${c==='jump'?' · '+Number(e.relation?.betweenRest||0)+' s':''}</span>`}
function eligibleStats(e){return e.relation?.type!=='drop'}
function matchingHistoryForSuggestion(ex){const type=ex.relation?.type||'';return historyMatching(ex).filter(e=>type==='backoff'||type==='drop'?(e.relation?.type||'')===type:!['backoff','drop'].includes(e.relation?.type||''))}
function filteredStatHistory(){const prefs=data.statsPrefs||{};return data.history.filter(h=>(!prefs.programId||h.programId===prefs.programId)&& (prefs.programId||(!prefs.from||h.date.slice(0,10)>=prefs.from)&&(!prefs.to||h.date.slice(0,10)<=prefs.to)))}
function toggleSearchMarkup(id,label){return `<div class="row"><button class="btn secondary small" data-action="toggleSearch" data-target="${id}">⌕ Cerca ${label}</button></div><div id="${id}" class="search-collapsed">${field('Cerca per nome, variante o attrezzo','search'+id)}</div>`}
function keyEx(e){return [e.name,e.variant,e.equipment,e.brand].map(s=>String(s||'').trim().toLocaleLowerCase('it')).join('|')}
function bestRecentSet(h){const sets=(h.setsDone||[]).filter(x=>x.done);if(!sets.length)return null;return [...sets].sort((a,b)=>{const ak=effectiveKg(h,a),bk=effectiveKg(h,b);if(ak!==null&&bk!==null)return bk-ak||Number(b.reps)-Number(a.reps);if(ak!==null)return -1;if(bk!==null)return 1;return (Number(b.loadValue)||0)-(Number(a.loadValue)||0)||Number(b.reps)-Number(a.reps)})[0]}
function sessionExercise(ex){const recent=matchingHistoryForSuggestion(ex).find(h=>(h.setsDone||[]).some(v=>v.done));const n=Math.max(1,Number(ex.sets)||1);const recentBest=recent?bestRecentSet(recent):null;const historicalUnit=unitForExercise(ex);const safeRecent=recentBest&&(!historicalUnit||canonicalUnit(recentBest.loadType||recent?.loadType)===historicalUnit)?recentBest:null;return {...clone(ex),setsDone:Array.from({length:n},()=>({reps:ex.reps?.includes('-')?ex.reps.split(/[-–]/).at(-1).trim():ex.reps,loadType:['rm','percent'].includes(ex.loadType)?(unitForExercise(ex)||'kg'):ex.loadType,loadUnit:['rm','percent'].includes(ex.loadType)?'kg':ex.loadUnit,loadValue:['rm','percent'].includes(ex.loadType)?'':ex.loadValue,pace:ex.pace||'',done:false})),suggestion:safeRecent,clusterCount:ex.clusterCount||2}}
function sessionQuick(e,i){const isDist=['distance','pace'].includes(e.loadType),isDur=e.loadType==='duration';return `<div class="session-plan"><span class="plan-caption">SCHEDA PROGRAMMATA</span><span>Sets <b>${esc(e.sets)}</b></span><span>${isDist?(e.loadType==='pace'?'Passo':'Distanza'):isDur?'Durata':'Reps'} <b>${esc(isDist?(e.loadType==='pace'?e.pace||'—':e.loadValue||'—'):isDur?e.loadValue||'—':e.reps||'—')}</b></span><span>Carico <b>${esc(loadLabel(e))}</b></span><span>Recupero <b>${esc(e.restSeconds||0)} s</b></span><span>Intensità <b>${esc(e.intensityType?e.intensityType+' '+(e.intensityValue||''):'—')}</b></span></div>`}

function sessionSet(e,i,s,j){const t=s.loadType||'kg',distance=t==='distance',pace=t==='pace',duration=t==='duration';const planned=['rm','percent'].includes(e.loadType)?effectiveKg(e,{loadType:e.loadType,loadValue:e.loadValue}):null;const options=types.filter(([k])=>!['rm','percent'].includes(k));return `<div class="compact-set"><div class="set-line"><strong class="set-number">Set ${j+1} <span class="set-ex-name">(${esc(e.name)})</span><label class="done-inline"><input type="checkbox" data-setfield="done" data-ex="${i}" data-set="${j}" ${s.done?'checked':''}> <span class="done-word">Eseguito</span></label></strong>${trash('removeSet',`data-index="${i}" data-set="${j}"`,'Rimuovi set')}</div><div class="set-entry${!distance&&!duration&&!pace&&e.intensityType==='RPE'&&j===0?' set-entry-reps-rpe':!distance&&!duration&&!pace?' set-entry-reps-only':''}">${select('Misura','setLoadType',options,t).replace('data-field="setLoadType"',`data-setfield="loadType" data-ex="${i}" data-set="${j}"`)}<div>${field(pace?'Distanza (km)':'Valore','setLoadValue',s.loadValue,'number','step="any"').replace('data-field="setLoadValue"',`data-setfield="loadValue" data-ex="${i}" data-set="${j}"`)}${planned!==null?`<small class="set-estimate">(${e.loadType==='percent'?esc(e.loadValue)+'% 1RM':esc(e.loadValue)+' RM'} → ${planned.toFixed(2)} ${t==='bwplus'?'kg + BW':'kg'} suggeriti)</small>`:''}</div>${distance||duration?select('Unità','setLoadUnit',loadUnit(t),s.loadUnit||e.loadUnit).replace('data-field="setLoadUnit"',`data-setfield="loadUnit" data-ex="${i}" data-set="${j}"`):''}${distance?'':pace?field('Passo (mm:ss/km)','setPace',s.pace||'').replace('data-field="setPace"',`data-setfield="pace" data-ex="${i}" data-set="${j}"`):duration?'':field('Reps','setReps',s.reps).replace('data-field="setReps"',`data-setfield="reps" data-ex="${i}" data-set="${j}"`)}${!distance&&!duration&&!pace&&e.intensityType==='RPE'&&j===0?field('RPE','setRPE',s.rpe??'','number','min="1" max="10" step="0.5"').replace('data-field="setRPE"',`data-setfield="rpe" data-ex="${i}" data-set="${j}"`):''}</div>${clusterControls(e,i,s,j)}</div>`}
function sessionDetails(ex){
 const rows=Array.isArray(ex.settings)?ex.settings:[];
 const settings=rows.filter(x=>x&&(String(x.label??x.detail??'').trim()||String(x.value??'').trim()));
 const notes=String(ex.notes??'').trim();
 const muscles=Array.isArray(ex.muscles)?ex.muscles.filter(Boolean).join(', '):String(ex.muscles??'').trim();
 const section=(title,content)=>`<details class="session-settings"><summary>${title}</summary><div class="session-settings-content">${content}</div></details>`;
 return (settings.length?section('Settings',settings.map(x=>`<div><span>${esc(x.label??x.detail??'Dettaglio')}:</span> <strong>${esc(x.value??'—')}</strong></div>`).join('')):'')+
 (notes?section('Indicazioni',`<div>${esc(notes)}</div>`):'')+
 (muscles?section('Muscoli',`<div>${esc(muscles)}</div>`):'');
}
function renderSessionExercise(e,i){const done=e.skipped||(e.setsDone.length>0&&e.setsDone.every(s=>s.done));return `<article class="card exercise ${e.category==='top'?'top-sets':''} ${e.relation?.parentId?'linked-exercise linked-arrow':''}" data-session-ex="${i}">${relationBadge(e)}${fixedTables(session.exercises,e,'session')}<div class="row"><div>${exerciseTitle(e)}</div><button class="btn secondary small" data-action="sessionEdit" data-index="${i}">Modifica</button></div>${sessionDetails(e)}${sessionQuick(e,i)}${nextRelationNotice(session.exercises,i)}<div class="session-advice">${e.intensityType==='RPE'&&rpeBest(e,e.intensityValue)?`<span>(RPE ${esc(e.intensityValue)}: ${rpeBest(e,e.intensityValue).kg.toFixed(2)} ${unitForExercise(e)==='bwplus'?'kg + BW':'kg'} × ${rpeBest(e,e.intensityValue).reps})</span>`:''}${e.suggestion?`<span>(Last: ${actualSetLabel(e,e.suggestion)} × ${esc(e.suggestion.reps)})</span>`:''}</div><div class="set-heading"><details class="sets-fold" data-index="${i}"><summary>Sets da eseguire (${e.setsDone.length})</summary><div class="setlist">${e.setsDone.map((s,j)=>sessionSet(e,i,s,j)).join('')}<button class="btn danger small skip-btn" data-action="skipExercise" data-index="${i}">Skip</button></div></details><button class="btn secondary small" data-action="addSet" data-index="${i}">+ Set</button></div><div class="exercise-move"><button class="btn secondary small" data-action="sessionMoveExercise" data-index="${i}" data-dir="-1" ${i===0?'disabled':''}>↑</button><button class="btn secondary small" data-action="sessionMoveExercise" data-index="${i}" data-dir="1" ${i===session.exercises.length-1?'disabled':''}>↓</button></div></article>`}
function renderSession(){if(!session)return '';const completed=session.exercises.map((e,i)=>({e,i})).filter(x=>(x.e.skipped||(x.e.setsDone.length&&x.e.setsDone.every(s=>s.done)))),remaining=session.exercises.map((e,i)=>({e,i})).filter(x=>!x.e.skipped&&(!x.e.setsDone.length||!x.e.setsDone.every(s=>s.done)));const controls=`<div class="toolbar">${btn('+ Nuovo esercizio','sessionAddExercise','')}${btn('Archivio','sessionPickLibrary')}</div>`;return `<div class="row"><h2>${esc(session.dayName)}</h2><span class="pill">In corso</span></div><p class="hint">I set eseguiti alimentano lo storico. Le modifiche non alterano la scheda originale.</p>${fixedTop('session')}${controls}${completed.length?`<details class="completed-section"><summary>✓ Completati (${completed.length})</summary>${completed.map(x=>renderSessionExercise(x.e,x.i)).join('')}</details>`:''}${remaining.map(x=>renderSessionExercise(x.e,x.i)).join('')}${controls}<div class="toolbar">${btn('Termina e salva','finishSession','')}${btn('Abbandona','discardSession','danger')}</div>`}

function renderHistory(){return `<h2>Storico</h2><div class="toolbar"><button class="btn secondary small" data-action="historyBody">Valori Corporei</button><button class="btn secondary small" data-action="historyPR">PR</button><button class="btn secondary small" data-action="historyPWR">PWR</button><button class="btn secondary small" data-action="historyRPE">RPE</button></div><div class="cols">${field('Programma','filterProgram','')}${field('Giornata','filterDay','')}${field('Esercizio','filterExercise','')}${field('Data','filterDate','','date')}</div><div id="historyResults"></div>`}
function drawHistory(){const e=$('#historyResults');if(!e)return;const v=k=>(document.querySelector(`[data-field="${k}"]`)?.value||'').toLocaleLowerCase('it');const list=data.history.filter(h=>(!v('filterProgram')||h.programName.toLowerCase().includes(v('filterProgram')))&&(!v('filterDay')||h.dayName.toLowerCase().includes(v('filterDay')))&&(!v('filterDate')||h.date.slice(0,10)===v('filterDate'))&&(!v('filterExercise')||h.exercises.some(x=>[x.name,x.variant,x.equipment].join(' ').toLowerCase().includes(v('filterExercise'))))).sort((a,b)=>b.date.localeCompare(a.date));e.innerHTML=list.length?list.map(h=>`<article class="card"><div class="row"><div><div class="title">${esc(h.dayName)}</div><div class="sub">${esc(h.programName)} · ${sessionTime(h.date)}</div></div><div class="row"><button class="btn secondary small" data-action="showHistory" data-id="${h.id}">Apri</button><button class="btn secondary small" data-action="editHistory" data-id="${h.id}">Modifica</button>${trash('deleteHistory',`data-id="${h.id}"`,'Elimina definitivamente la sessione')}</div></div><div class="sub">${h.exercises.length} esercizi</div></article>`).join(''):'<div class="empty">Nessuna sessione corrispondente.</div>'}
function drawPick(){const root=$('#pickResults');if(!root)return;const f=k=>String(document.querySelector(`[data-field="pick${k}"]`)?.value||'').toLowerCase();const list=sortedArchive(data.library).filter(x=>['Name','Muscles','Equipment','Brand'].every(k=>String(x[k.toLowerCase()==='name'?'name':k.toLowerCase()]||'').toLowerCase().includes(f(k))));root.innerHTML=list.map(x=>`<button class="btn secondary" style="display:block;width:100%;margin:8px 0;text-align:left" data-action="useLibrary" data-id="${x.id}">${esc(x.name)} · ${esc(x.variant)} · ${esc(x.equipment)}</button>`).join('')||'<p>Nessun risultato.</p>'}
