document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(b){try{await action(b.dataset.action,b)}catch(err){alert('Errore: '+err.message)}}});document.addEventListener('submit',async e=>{if(e.target.id!=='exerciseForm')return;e.preventDefault();try{const f=e.target,context=f.dataset.context,x=formEx();if(context==='day'){const i=day().exercises.findIndex(z=>z.id===x.id);if(i<0){const parent=day().exercises.findIndex(e=>e.id===x.relation?.parentId);day().exercises.splice(parent<0?day().exercises.length:parent+1,0,x)}else day().exercises[i]=x;await save()}else if(context==='library'){const i=data.library.findIndex(z=>z.id===x.id);if(i<0)data.library.push(x);else data.library[i]=x;await save()}else if(context==='session-new'){{const parent=session.exercises.findIndex(e=>e.id===x.relation?.parentId);session.exercises.splice(parent<0?session.exercises.length:parent+1,0,sessionExercise(x))}await saveDraft()}else if(context.startsWith('session:')){const i=Number(context.split(':')[1]);pendingSessionEdit={index:i,exercise:x};closeModal();modal({title:'Dove salvare le modifiche?',body:`<p class="hint">Scegli una sola destinazione. Le altre copie resteranno invariate.</p><div class="toolbar save-targets"><button class="btn secondary" data-action="commitSessionEdit" data-target="session">Allenamento in corso</button><button class="btn secondary" data-action="commitSessionEdit" data-target="day">Scheda programmata</button><button class="btn secondary" data-action="commitSessionEdit" data-target="archive">Archivio</button></div>`});return} closeModal();render();toast('Esercizio salvato')}catch(err){alert(err.message)}});document.addEventListener('change',e=>{if(e.target.matches('[data-field="loadType"]')){const f=$('#exerciseForm');f.dataset.loadValue='';f.dataset.pace='';f.dataset.loadUnit=e.target.value==='duration'?'sec':['distance','pace'].includes(e.target.value)?'km':'kg';drawLoadFields()}if(e.target.matches('[data-field="intensityType"]')){const f=$('#exerciseForm');f.dataset.intensityValue='';drawIntensityFields()}if(e.target.matches('[data-setfield]'))syncSetInput(e.target);if(e.target.matches('[data-quick]')){syncQuick(e.target);if(['intensityValue','intensityType','loadValue'].includes(e.target.dataset.quick))render()}if(e.target.id==='importFile'&&e.target.files[0])importBackup(e.target.files[0])});document.addEventListener('input',e=>{if(e.target.matches('[data-quick]')&&e.target.dataset.quick!=='sets')syncQuick(e.target);if(e.target.matches('[data-field^="pick"]'))drawPick();if(e.target.matches('[data-setfield]'))syncSetInput(e.target);if(e.target.matches('[data-quick]'))syncQuick(e.target);if(e.target.matches('[data-field="loadValue"]')){ $('#exerciseForm').dataset.loadValue=e.target.value;const f=$('#exerciseForm'),el=$('#loadEstimate');if(el)el.textContent=estimateLabel(f.querySelector('[data-field="loadType"]').value,e.target.value,f)}if(e.target.matches('[data-field="pace"]'))$('#exerciseForm').dataset.pace=e.target.value;if(e.target.matches('[data-field="loadUnit"]'))$('#exerciseForm').dataset.loadUnit=e.target.value;if(e.target.matches('[data-field="intensityValue"]'))$('#exerciseForm').dataset.intensityValue=e.target.value});$$('#nav button').forEach(b=>b.addEventListener('click',()=>{if(session&&page==='session'&&!confirm('La sessione in corso non è ancora salvata. Vuoi lasciarla aperta e cambiare pagina?'))return;page=b.dataset.page;render()}));$('#settingsBtn').addEventListener('click',()=>{page='settings';render()});$('#profileBtn').addEventListener('click',()=>{page='profile';render()});
